import{_ as e,o as d,c as r,a4 as l}from"./chunks/framework.BMj-uaUw.js";const p=JSON.parse('{"title":"课程导读","description":"","frontmatter":{},"headers":[{"level":2,"title":"这门课解决什么问题","slug":"这门课解决什么问题","link":"#这门课解决什么问题","children":[]},{"level":2,"title":"学完这门课，你应该能够","slug":"学完这门课-你应该能够","link":"#学完这门课-你应该能够","children":[]},{"level":2,"title":"课程在专业链条中的位置","slug":"课程在专业链条中的位置","link":"#课程在专业链条中的位置","children":[]},{"level":2,"title":"学时分配","slug":"学时分配","link":"#学时分配","children":[]},{"level":2,"title":"一次课是怎么过的","slug":"一次课是怎么过的","link":"#一次课是怎么过的","children":[]},{"level":2,"title":"考核方式","slug":"考核方式","link":"#考核方式","children":[]},{"level":2,"title":"综合项目","slug":"综合项目","link":"#综合项目","children":[]},{"level":2,"title":"你需要准备什么","slug":"你需要准备什么","link":"#你需要准备什么","children":[]},{"level":2,"title":"三个学习建议","slug":"三个学习建议","link":"#三个学习建议","children":[]},{"level":2,"title":"怎么往下读","slug":"怎么往下读","link":"#怎么往下读","children":[]}],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1789500889000}'),i={name:"guide/index.md"};function a(n,t,o,h,s,u){return d(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="课程导读" tabindex="-1">课程导读 <a class="header-anchor" href="#课程导读" aria-label="Permalink to &quot;课程导读&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">一句话定位</p><p>这门课不教你写第一个网页，而是教你把一个能跑的网页，变成一个<strong>能交付、能协作、能维护</strong>的工程。</p></div><h2 id="这门课解决什么问题" tabindex="-1">这门课解决什么问题 <a class="header-anchor" href="#这门课解决什么问题" aria-label="Permalink to &quot;这门课解决什么问题&quot;">​</a></h2><p>先看几个几乎每个前端新手都会遇到的场面。</p><ul><li>代码写完能跑，但换台电脑就报错，因为&quot;我记得装过某个包&quot;。</li><li>三个人一起写，合并代码时冲突一堆，谁都不敢动别人的文件。</li><li>页面上线后用户反馈白屏，本地怎么试都是好的。</li><li>需求改一次，同样的逻辑要在五个文件里各改一遍。</li><li>接口一慢，页面就卡在那里转圈，用户不知道发生了什么。</li></ul><p>这些问题的共同点是：<strong>它们都不是&quot;语法不会&quot;造成的</strong>。语法可以查文档，而上面这些是工程问题 —— 属于 怎么组织代码、怎么管理依赖、怎么保证质量、怎么协作交付的范畴。</p><p>前端工程化要做的，就是把这些靠&quot;经验&quot;和&quot;小心&quot;来避免的麻烦，变成<strong>有工具、有流程、有约定</strong>的常规动作。</p><h2 id="学完这门课-你应该能够" tabindex="-1">学完这门课，你应该能够 <a class="header-anchor" href="#学完这门课-你应该能够" aria-label="Permalink to &quot;学完这门课，你应该能够&quot;">​</a></h2><p><strong>知识层面</strong></p><ul><li>说清前端工程化要解决的六类问题：模块化、依赖管理、编译转换、质量保障、自动化、协作交付。</li><li>说清一个现代前端项目的目录结构、配置文件、脚本命令各自在做什么。</li><li>说清 Vue 的响应式是怎么知道&quot;数据变了&quot;的，以及为什么有些写法会失去响应性。</li><li>说清单页应用的路由、状态管理、请求层三者之间的职责边界。</li></ul><p><strong>能力层面</strong></p><ul><li>在一台干净机器上，从零搭出一个带检查、格式化、提交钩子的前端工程。</li><li>独立完成一个完整的业务页面：列表、表单、状态流转、加载与错误处理。</li><li>用 Vue 3 组合式 API 拆组件、抽组合式函数、写自定义指令。</li><li>用路由守卫与状态管理实现一套完整的登录鉴权。</li><li>把项目打包、部署到服务器，并写出让别人能跑起来的说明文档。</li><li>（延伸）用 uni-app 把同一套后端接口接到手机端，一套代码编译到 H5 与微信小程序。</li></ul><p><strong>素养层面</strong></p><ul><li>养成&quot;先想清楚再写&quot;的习惯：需求 → 页面清单 → 接口清单 → 代码。</li><li>对异常状态有敏感度：宁可多写一个错误提示，也不让用户对着白屏猜。</li><li>会用工具查问题，而不是靠反复试。</li></ul><h2 id="课程在专业链条中的位置" tabindex="-1">课程在专业链条中的位置 <a class="header-anchor" href="#课程在专业链条中的位置" aria-label="Permalink to &quot;课程在专业链条中的位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关系</th><th>课程</th><th>学时</th><th>本课程与之的接口</th></tr></thead><tbody><tr><td>前序</td><td>Web 前端基础</td><td>—</td><td>需要你已掌握 HTML、CSS、JavaScript 基础语法与 DOM 操作</td></tr><tr><td>平行</td><td>后端工程化开发</td><td>64</td><td>本课程第 9 周起对接其 REST 接口，联调时共用一套接口约定</td></tr><tr><td>本课程</td><td><strong>前端工程化开发</strong></td><td><strong>48</strong></td><td>—</td></tr><tr><td>后续</td><td>Web 应用系统综合实训</td><td>72</td><td>本课程的工程骨架与规范可直接复用，换业务载体后做完整完整链路</td></tr></tbody></table><p>一句话说清边界：<strong>这门课负责把前端工程的地基和框架用法讲透，业务复杂度保持在&quot;够练手&quot;的程度； 更复杂的业务在综合实训里做。</strong></p><h2 id="学时分配" tabindex="-1">学时分配 <a class="header-anchor" href="#学时分配" aria-label="Permalink to &quot;学时分配&quot;">​</a></h2><p>总共 48 学时，按 12 周 × 4 学时安排，每周一个单元，<strong>一个单元正好一次课</strong>。</p><table tabindex="0"><thead><tr><th>模块</th><th>主题</th><th>学时</th><th>周次</th></tr></thead><tbody><tr><td>一</td><td>工程化认知与工具链</td><td>12</td><td>第 1 - 3 周</td></tr><tr><td>二</td><td>Vue 3 核心基础</td><td>12</td><td>第 4 - 6 周</td></tr><tr><td>三</td><td>组件化开发</td><td>8</td><td>第 7 - 8 周</td></tr><tr><td>四</td><td>应用架构</td><td>8</td><td>第 9 - 10 周</td></tr><tr><td>五</td><td>综合项目实战</td><td>8</td><td>第 11 - 12 周</td></tr></tbody></table><p>理论讲讲授与实践的比例大致是 1 : 2。工具链占了 12 学时，是因为这部分恰恰是学生最缺、 遇到问题时最耗时间的环节 —— 前置讲透，后面 36 学时的写代码效率会明显提高。</p><h2 id="一次课是怎么过的" tabindex="-1">一次课是怎么过的 <a class="header-anchor" href="#一次课是怎么过的" aria-label="Permalink to &quot;一次课是怎么过的&quot;">​</a></h2><p>每次课 4 学时，按下面的节奏推进：</p><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>现场抽问本单元的知识点，确认示例都跑过</td></tr><tr><td>讲解</td><td>1.3 学时</td><td>只讲重点与容易踩的坑，不逐行念代码</td></tr><tr><td>现场任务</td><td>1.8 学时</td><td>做本单元的实训任务，老师在教室里走动排错</td></tr><tr><td>复盘</td><td>0.6 学时</td><td>展示两三个同学的写法，对比不同解法的取舍</td></tr></tbody></table><p>课内时间不够讲完所有细节，所以<strong>每个单元都标注了配套章节，要求课前通读并跑通示例</strong>。 课后作业以&quot;改造 + 排错&quot;为主，不布置照抄题。</p><h2 id="考核方式" tabindex="-1">考核方式 <a class="header-anchor" href="#考核方式" aria-label="Permalink to &quot;考核方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>占比</th><th>评分项</th></tr></thead><tbody><tr><td>过程性</td><td>40%</td><td>课堂实训任务完成度（20%）、课后案例作业（15%）、出勤与课堂参与（5%）</td></tr><tr><td>阶段性</td><td>20%</td><td>工程模板验收（第 3 周，10%）、路由与状态综合任务（第 10 周，10%）</td></tr><tr><td>终结性</td><td>40%</td><td>综合项目源码与功能（15%）、部署与演示（10%）、答辩与文档（15%）</td></tr></tbody></table><p>所有评分项都有可留存的证据：代码仓库、提交记录、部署地址、评审记录。<strong>没有闭卷记忆类考核。</strong></p><h2 id="综合项目" tabindex="-1">综合项目 <a class="header-anchor" href="#综合项目" aria-label="Permalink to &quot;综合项目&quot;">​</a></h2><p>项目是<strong>校园活动服务平台</strong>，取“活动发布 → 报名审核 → 场次安排”这条主线。它有两个端：</p><table tabindex="0"><thead><tr><th>端</th><th>做什么</th><th>技术</th><th>是否占用课时</th></tr></thead><tbody><tr><td>管理端</td><td>组织者发布活动、审核员审批报名、排场次与场地</td><td>Vue 3 + Vite + Element Plus</td><td>是，贯穿 12 个单元</td></tr><tr><td>用户端</td><td>学生用手机看活动、报名、查报名记录</td><td>uni-app + Wot UI</td><td>否，独立专栏，课后延伸</td></tr></tbody></table><p>管理端规模控制在 12 周内能完成的范围；用户端是管理端跑通之后的第二个端，5 个页面， 共用一套后端接口。两端的详细规格都在项目文档里。</p><p>项目从第 3 周建仓库就开始，之后每周的课堂练习都在同一个工程里做，第 11 - 12 周只做收口。 这样安排的原因很实际：课内留给项目的时间只有 8 学时，如果等到第 11 周才动手，一定做不完。</p><ul><li><a href="/frontend-engineering-course/project/">项目总览</a></li><li><a href="/frontend-engineering-course/project/requirements.html">管理端需求规格</a></li><li><a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a></li><li><a href="/frontend-engineering-course/project/rules.html">业务规则与状态流转</a></li></ul><h2 id="你需要准备什么" tabindex="-1">你需要准备什么 <a class="header-anchor" href="#你需要准备什么" aria-label="Permalink to &quot;你需要准备什么&quot;">​</a></h2><p><strong>基础</strong>：会写 HTML 结构、能用 CSS 做基本布局、看得懂 JavaScript 的函数与数组方法。 如果这几项不熟，建议先补前面那门课 —— 这门课不会停下来讲 <code>const</code> 和 <code>for</code> 循环。</p><p><strong>机器</strong>：一台能装 Node.js 的电脑，8 GB 内存以上。不需要独立显卡。</p><p><strong>心态</strong>：这门课会遇到大量报错。报错不是失败，是工具在替你干活。<strong>学会读报错，比记住语法更重要。</strong></p><h2 id="三个学习建议" tabindex="-1">三个学习建议 <a class="header-anchor" href="#三个学习建议" aria-label="Permalink to &quot;三个学习建议&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">关于&quot;抄代码&quot;</p><p>抄代码本身没问题，问题是抄完不看结果。教程里的每一段代码都能跑， 建议<strong>抄一遍 → 改几个地方 → 看变化</strong>。改完之后还能解释为什么变化，才算真会了。</p></div><p><strong>一、把每一章的示例都在自己的工程里跑一遍</strong></p><p>只看不写，等于没学。工程化的知识，一半在配置文件的细节里，另一半在报错的解决过程里。</p><p><strong>二、遇到问题先看报错的最后一行</strong></p><p>绝大多数报错信息已经写清了原因和位置。教程的<a href="/frontend-engineering-course/appendix/errors.html">常见报错与排查</a>整理了高频问题， 但更重要的是养成&quot;从报错里找线索&quot;的习惯。</p><p><strong>三、给每个单元留一份产出</strong></p><p>每个单元都有明确的课堂产出（配置模板、状态模块、业务页面）。这些产出不是应付检查的， 它们会直接成为综合项目的一部分。认真做，项目阶段能省一半力气。</p><h2 id="怎么往下读" tabindex="-1">怎么往下读 <a class="header-anchor" href="#怎么往下读" aria-label="Permalink to &quot;怎么往下读&quot;">​</a></h2><ul><li>想先搞清楚整门课的地图 → <a href="/frontend-engineering-course/guide/roadmap.html">12 周课程地图</a></li><li>想先弄明白前端整体的学习路径和方向 → <a href="/frontend-engineering-course/guide/learning-path.html">前端学习路线</a></li><li>准备开始动手，先把环境弄干净 → <a href="/frontend-engineering-course/guide/environment.html">开发环境准备</a></li><li>想知道这套教程有哪些用法 → <a href="/frontend-engineering-course/guide/how-to-use.html">怎么用这套教程</a></li><li>准备开始写代码，想知道 AI 该怎么用 → <a href="/frontend-engineering-course/guide/ai-coding.html">AI 编程：用之前先知道它的边界</a></li><li>管理端做完了，想给项目加个手机端 → <a href="/frontend-engineering-course/mobile/">用户端 · uni-app 实战</a></li></ul>',48)])])}const c=e(i,[["render",a]]);export{p as __pageData,c as default};
